parameters.jsCode:
const body = $input.first().json.body;
const required = ['endpoint_path', 'http_method', 'description'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
const methods = ['GET','POST','PUT','PATCH','DELETE'];
const method = methods.includes((body.http_method||'').toUpperCase()) ? body.http_method.toUpperCase() : 'GET';
return [{ json: {
  valid: true,
  endpointPath: body.endpoint_path.trim(),
  httpMethod: method,
  description: body.description.trim().slice(0,500),
  authType: body.auth_type || 'Bearer token',
  pathParams: body.path_params || [],
  queryParams: body.query_params || [],
  requestBodySchema: body.request_body_schema || null,
  responseBodySchema: body.response_body_schema || null,
  errorCodes: body.error_codes || [],
  rateLimits: body.rate_limits || '',
  exampleUseCase: body.example_use_case || '',
  apiName: body.api_name || 'API',
  baseUrl: body.base_url || 'https://api.example.com',
  replyEmail: body.reply_email || null
} }];

