parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let docs;
try { docs = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
docs._meta = { apiName: input.apiName, endpointPath: input.endpointPath, httpMethod: input.httpMethod, replyEmail: input.replyEmail };
return [{ json: docs }];

const d = $input.first().json;
const m = d._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const methodColors = {GET:'#16a34a',POST:'#2563eb',PUT:'#d97706',PATCH:'#7c3aed',DELETE:'#dc2626'};
const mc = methodColors[m.httpMethod]||'#6b7280';
const paramTable = (rows,headers) => rows && rows.length ? `<table style="width:100%;border-collapse:collapse;margin-bottom:16px"><thead><tr style="font-size:11px;text-transform:uppercase;color:#9ca3af">${headers.map(h=>`<th style="padding:6px 10px;text-align:left">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr style="border-bottom:1px solid #f3f4f6;font-size:13px"><td style="padding:6px 10px;font-family:monospace">${esc(r.name||r.field||r.code)}</td><td style="padding:6px 10px;color:#6b7280">${esc(r.type||r.meaning||'')}</td><td style="padding:6px 10px">${r.required!==undefined?(r.required?'✓':'—'):''}${r.common_cause?esc(r.common_cause):''}</td><td style="padding:6px 10px;color:#374151">${esc(r.description||'')}</td></tr>`).join('')}</tbody></table>` : '';
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,sans-serif;color:#111"><div style="max-width:720px;margin:0 auto"><div style="background:#111827;color:#fff;padding:20px 28px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;color:#6b7280">${esc(m.apiName)} API Docs</div><div style="display:flex;gap:10px;align-items:center;margin-top:6px"><span style="background:${mc};color:#fff;font-size:12px;font-weight:700;padding:3px 10px;border-radius:4px">${esc(m.httpMethod)}</span><code style="font-size:15px">${esc(m.endpointPath)}</code></div></div><div style="background:#fff;padding:18px 28px;border:1px solid #e5e7eb;border-top:none"><h2 style="font-size:18px;margin:0 0 6px">${esc(d.title)}</h2><p style="font-size:14px;color:#374151;line-height:1.6">${esc(d.summary)}</p></div><div style="background:#1e293b;padding:16px 28px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6"><pre style="color:#86efac;font-size:13px;overflow-x:auto;margin:0;white-space:pre-wrap">${esc(d.example_curl)}</pre></div>${paramTable(d.path_params_table,['Name','Type','Required',''])?`<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb"><h3 style="font-size:13px;text-transform:uppercase;color:#9ca3af">Path Parameters</h3>${paramTable(d.path_params_table,['Name','Type','Required',''])}</div>`:''}${paramTable(d.query_params_table,['Name','Type','Required',''])?`<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb"><h3 style="font-size:13px;text-transform:uppercase;color:#9ca3af">Query Parameters</h3>${paramTable(d.query_params_table,['Name','Type','Required',''])}</div>`:''}<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb"><h3 style="font-size:13px;text-transform:uppercase;color:#9ca3af">Example Response</h3><pre style="background:#f9fafb;padding:12px;border-radius:6px;font-size:12px;overflow-x:auto">${esc(d.example_response_success)}</pre></div>${paramTable(d.error_table,['Code','Meaning','Cause',''])?`<div style="background:#fff;padding:16px 28px;border:1px solid #e5e7eb"><h3 style="font-size:13px;text-transform:uppercase;color:#9ca3af">Errors</h3>${paramTable(d.error_table,['Code','Meaning','Cause',''])}</div>`:''}<div style="background:#111827;color:#4b5563;font-size:11px;padding:10px 28px;border-radius:0 0 10px 10px;text-align:center">API Docs Generator</div></div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, apiName: m.apiName, endpointPath: m.endpointPath, docs: d } }];
